// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skill.builtinimport com.roshan.persona.brain.skill.BrainSkillimport dagger.Bindsimport dagger.Moduleimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport dagger.multibindings.IntoSet/** * NOUS — Hilt module for built-in skills + Layer 2 infrastructure. * * Binds: *   - All built-in skills via `@Binds @IntoSet` multibinding * * Layer 2 infrastructure (executors, permission checker, credential vault, * embedder, NER) is provided by the respective feature modules: * * Feature modules can contribute their own skills by creating a similar * `@Module @InstallIn(SingletonComponent::class)` with `@Binds @IntoSet`. */@Module@InstallIn(SingletonComponent::class)abstract class BuiltInSkillsModule {    @Binds @IntoSet    abstract fun bindTorchSkill(impl: TorchSkill): BrainSkill    @Binds @IntoSet    abstract fun bindVolumeSkill(impl: VolumeSkill): BrainSkill    @Binds @IntoSet    abstract fun bindCallSkill(impl: CallSkill): BrainSkill    @Binds @IntoSet    abstract fun bindSmsSkill(impl: SmsSkill): BrainSkill    @Binds @IntoSet    abstract fun bindOpenAppSkill(impl: OpenAppSkill): BrainSkill    @Binds @IntoSet    abstract fun bindBrightnessSkill(impl: BrightnessSkill): BrainSkill}/** * Module providing Layer 2 infrastructure (executors + permission checker). * * **INTEGRATION FIX — Duplicate PermissionChecker binding removed.** * Both `:feature:brain` and `:feature:system` were providing PermissionChecker, * causing Hilt duplicate-binding compile error. The real `RealPermissionChecker` * from `:feature:system/di/SystemModule.kt` wins; brain no longer provides a fake. * * SystemOperationExecutor is also provided by `:feature:system`'s SystemModule * (SystemOperationExecutorImpl — real Android services). * * Strategy §14.2 Table 10 — Brain interface overrides (all completed): *   - FakePermissionChecker       → RealPermissionChecker (:feature:security) ✅ *   - FakeSystemOperationExecutor → SystemOperationExecutorImpl (:feature:system) ✅ *   - NoOpCredentialVault         → CredentialVaultImpl (:feature:security) ✅ *   - FakeEmbedder                → OmniSlmEmbedder (:feature:vision) ✅ *   - null NerModel               → OmniSlmNerModel (:feature:vision) ✅ *   - NoOpAuditLogPersistence     → EncryptedAuditLogPersistence (:feature:security) ✅ * * All previous stubs/fakes have been replaced with real production * implementations across the 35-module Hilt graph. */@Module@InstallIn(SingletonComponent::class)object SkillInfrastructureModule {    // PermissionChecker — REMOVED (provided by :feature:system's SystemModule).    // SystemOperationExecutor — REMOVED (provided by :feature:system's SystemModule).    // CredentialVaultInterface — REMOVED (provided by :feature:security's SecurityModule).    // EmbedderInterface — REMOVED (provided by :feature:vision's VisionModule).    // NerModelInterface — REMOVED (provided by :feature:vision's VisionModule).    // AuditLogPersistence — REMOVED (provided by :feature:security's SecurityModule).    //    // This module is kept (currently empty body) as a documentation anchor    // for the integration pattern above.}